import React, { useState, useEffect } from 'react'
import { Container, Row, Col, Table, Button, Badge } from 'reactstrap'
import { BASE_URL } from '../../utils/config'

const ManageUsers = () => {
   const [users, setUsers] = useState([])
   const [loading, setLoading] = useState(true)
   const [error, setError] = useState(null)

   // Hàm lấy danh sách User
   useEffect(() => {
      const fetchUsers = async () => {
         try {
            // Gọi API (Backend của bạn hiện đã cho phép truy cập công khai route này)
            const res = await fetch(`${BASE_URL}/users`, {
               method: 'GET'
            })

            const result = await res.json()

            if (res.ok) {
               // Backend trả về { success: true, data: [...] } nên ta lấy result.data
               setUsers(result.data || []) 
            } else {
               setError(result.message || "Không thể tải danh sách người dùng")
            }
            setLoading(false)
         } catch (err) {
            setError("Lỗi kết nối đến Server! Vui lòng kiểm tra lại Backend.")
            setLoading(false)
         }
      }

      fetchUsers()
   }, [])

   // Hàm xóa User
   const deleteUser = async (id) => {
      if (window.confirm("Bạn có chắc chắn muốn xóa người dùng này?")) {
         try {
            const res = await fetch(`${BASE_URL}/users/${id}`, {
               method: 'DELETE'
            })
            const result = await res.json()
            
            if (res.ok) {
               alert("Xóa thành công!")
               // Cập nhật lại danh sách trên giao diện ngay lập tức
               setUsers(prev => prev.filter(user => user._id !== id))
            } else {
               alert(result.message)
            }
         } catch (err) {
            alert("Lỗi máy chủ khi thực hiện xóa!")
         }
      }
   }

   return (
      <section className="mt-5 pt-5">
         <Container>
            <Row>
               <Col lg='12'>
                  <div className="d-flex align-items-center justify-content-between mb-4">
                     <h3 className="fw-bold">Danh sách thành viên</h3>
                     <Badge color="info" className="p-2">
                        {users ? users.length : 0} Người dùng
                     </Badge>
                  </div>

                  {/* Trạng thái Loading */}
                  {loading && <h4 className="text-center pt-5">Đang tải dữ liệu...</h4>}

                  {/* Trạng thái Error */}
                  {error && <h4 className="text-center pt-5 text-danger">{error}</h4>}

                  {/* Bảng dữ liệu */}
                  {!loading && !error && (
                     <Table hover responsive className="shadow-sm bg-white rounded border overflow-hidden">
                        <thead className="bg-light">
                           <tr className="text-uppercase" style={{ fontSize: '0.9rem' }}>
                              <th className="py-3">Tên người dùng</th>
                              <th className="py-3">Email</th>
                              <th className="py-3">Vai trò</th>
                              <th className="py-3">Ngày tham gia</th>
                              <th className="py-3 text-center">Thao tác</th>
                           </tr>
                        </thead>
                        <tbody>
                           {users && users.length > 0 ? (
                              users.map(user => (
                                 <tr key={user._id} className="align-middle">
                                    <td className="fw-bold text-dark">{user.username}</td>
                                    <td>{user.email}</td>
                                    <td>
                                       <Badge color={user.role === 'admin' ? 'danger' : 'success'} pill>
                                          {user.role || 'user'}
                                       </Badge>
                                    </td>
                                    <td>
                                       {user.createdAt 
                                          ? new Date(user.createdAt).toLocaleDateString('vi-VN') 
                                          : 'N/A'
                                       }
                                    </td>
                                    <td className="text-center">
                                       <Button 
                                          color="danger" 
                                          outline 
                                          size="sm" 
                                          onClick={() => deleteUser(user._id)}
                                          title="Xóa người dùng"
                                       >
                                          <i className="ri-delete-bin-line"></i>
                                       </Button>
                                    </td>
                                 </tr>
                              ))
                           ) : (
                              <tr>
                                 <td colSpan="5" className="text-center py-4 text-muted">
                                    Không có dữ liệu người dùng để hiển thị.
                                 </td>
                              </tr>
                           )}
                        </tbody>
                     </Table>
                  )}
               </Col>
            </Row>
         </Container>
      </section>
   )
}

export default ManageUsers
